package com.lapakhunian.app.core.designsystem

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * Path vektor glyph Phosphor yang dipakai app (digenerate dari font via fontTools).
 * Dipakai PhIcon sebagai pengganti render font-icon: ImageVector bebas dari
 * clipping metrik font / fontScale / quirk OEM — presisi identik di semua device.
 * Koordinat = grid Phosphor 1024 (y sudah dibalik ke arah turun), viewport 1024.
 * Jangan edit manual; regenerate via script fontTools.
 */
private fun buildPhosphorVector(name: String, d: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 1024f,
        viewportHeight = 1024f,
    ).apply {
        addPath(
            pathData = PathParser().parsePathString(d).toNodes(),
            fill = SolidColor(Color.Black),
            pathFillType = PathFillType.NonZero,
        )
    }.build()

